CREATE DATABASE IF NOT EXISTS ideal_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ideal_db;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','manager','seller') NOT NULL DEFAULT 'seller', active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, category VARCHAR(100), sale_price BIGINT NOT NULL DEFAULT 0, cost_price BIGINT NOT NULL DEFAULT 0, stock INT NOT NULL DEFAULT 0, image TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, phone VARCHAR(40), email VARCHAR(190), address TEXT);
CREATE TABLE purchases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, supplier_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity INT NOT NULL, unit_cost BIGINT NOT NULL, total BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(supplier_id) REFERENCES suppliers(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE sales (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(80) NOT NULL UNIQUE, client VARCHAR(180) NOT NULL, phone VARCHAR(40), product_id BIGINT UNSIGNED NOT NULL, quantity INT NOT NULL, unit_price BIGINT NOT NULL, unit_cost BIGINT NOT NULL, total BIGINT NOT NULL, paid BIGINT NOT NULL, payment_method VARCHAR(60), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE debts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sale_id BIGINT UNSIGNED NOT NULL, amount BIGINT NOT NULL, paid BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(sale_id) REFERENCES sales(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, details TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));

-- Stockage centralisé de l'état de l'application (synchronisation multi-appareils)
CREATE TABLE IF NOT EXISTS app_state (
  id TINYINT UNSIGNED PRIMARY KEY,
  payload LONGTEXT NOT NULL,
  updated_by BIGINT UNSIGNED NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_app_state_user FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL
);
